import styled from '@emotion/styled';

export const StyledPOSHeaderContainer = styled.div({
  display: 'flex',
  width: '100%',
  justifyContent: 'space-between',
  alignItems: 'center',
});

interface StyledPOSContentSectionProps {
  $marginBottom?: boolean;
}

export const StyledPOSContentSection = styled.div<StyledPOSContentSectionProps>(
  ({ $marginBottom }) => ({
    width: '1290px',
    display: 'grid',
    gap: '24px',
    marginBottom: $marginBottom ? '48px' : '0px',
  }),
);
